from fnmatch import fnmatch

def da_ignorare(percorsi, regole):
    out = []
    for p in percorsi:
        parti = p.split("/")
        cartelle, nome = parti[:-1], parti[-1]
        for r in regole:
            if r.endswith("/"):
                if r[:-1] in cartelle:
                    out.append(p)
                    break
            elif fnmatch(nome, r):
                out.append(p)
                break
    return out

print(da_ignorare([".venv/lib/x.py", "src/a.py", "log/oggi.log"], [".venv/", "*.log"]))
